-- Draggable Button
local dragging = false
local dragInput, dragStart, startPos

FloatingButton.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragging = true
        dragStart = input.Position
        startPos = FloatingButton.Position
    end
end)

FloatingButton.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragging = false
        local delta = input.Position - dragStart
        if delta.Magnitude < 5 then
            if MainMenu.Visible then
                local tw = TweenService:Create(MainMenu, TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Size = UDim2.new(0, 0, 0, 0), Position = FloatingButton.Position + UDim2.new(0, 25, 0, 25)})
                tw:Play()
                tw.Completed:Wait()
                MainMenu.Visible = false
                FloatingButton.Visible = true
            else
                MainMenu.Size = UDim2.new(0, 0, 0, 0)
                MainMenu.Position = FloatingButton.Position + UDim2.new(0, 25, 0, 25)
                MainMenu.Visible = true
                FloatingButton.Visible = false
                TweenService:Create(MainMenu, TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Size = UDim2.new(0, 550, 0, 350), Position = UDim2.new(0.5, -275, 0.5, -175)}):Play()
            end
        end
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
        dragInput = input
    end
end)

RunService.RenderStepped:Connect(function()
    if dragging and dragInput then
        local delta = dragInput.Position - dragStart
        FloatingButton.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
    end
end)

