-- Tabs
local currentTab = nil
local function CreateTab(name, yOffset)
    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(1, -20, 0, 30)
    btn.Position = UDim2.new(0, 10, 0, yOffset)
    btn.BackgroundColor3 = Color3.fromRGB(20, 20, 25)
    btn.Text = "  " .. name
    btn.TextColor3 = Color3.fromRGB(200, 200, 200)
    btn.Font = Enum.Font.GothamSemibold
    btn.TextSize = 13
    btn.TextXAlignment = Enum.TextXAlignment.Left
    btn.Parent = Sidebar
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 6)
    corner.Parent = btn
    
    local page = Instance.new("ScrollingFrame")
    page.Size = UDim2.new(1, -20, 1, -20)
    page.Position = UDim2.new(0, 10, 0, 10)
    page.BackgroundTransparency = 1
    page.ScrollBarThickness = 2
    page.Visible = false
    page.Parent = Content
    
    local layout = Instance.new("UIListLayout")
    layout.Padding = UDim.new(0, 10)
    layout.Parent = page
    
    btn.MouseButton1Click:Connect(function()
        if currentTab then
            currentTab.btn.BackgroundColor3 = Color3.fromRGB(20, 20, 25)
            currentTab.btn.TextColor3 = Color3.fromRGB(200, 200, 200)
            currentTab.page.Visible = false
        end
        btn.BackgroundColor3 = Color3.fromRGB(99, 102, 241)
        btn.TextColor3 = Color3.fromRGB(255, 255, 255)
        page.Visible = true
        currentTab = {btn = btn, page = page}
    end)
    
    return page, btn
end

